import hashlib,json,re,subprocess
from pathlib import Path
q=Path(__file__).parent

def normalize(asm,addr,size):
 lines=[]
 for line in asm.splitlines():
  m=re.match(r'^\s*([0-9a-f]+):\s*(.*)',line)
  if not m:continue
  s=re.split(r'\s+#\s+',m[2],maxsplit=1)[0];s=re.sub(r'-?0x[0-9a-f]+\(%rip\)','RIP_DISPLACEMENT(%rip)',s)
  branch=re.match(r'^(j\w+|call)\s+([0-9a-f]+)\s+<(.*)>$',s)
  if branch:
   t=int(branch[2],16);s=branch[1]+' '+(f'LOCAL_{t-addr:x}' if addr<=t<addr+size else branch[3])
  lines.append(f'{int(m[1],16)-addr:x}: '+ ' '.join(s.split()))
 return '\n'.join(lines)+'\n'

records={};norm={}
for v in ['before','after']:
 b=q/f'widen-bench-{v}';symbols=subprocess.check_output(['nm','-S','-C',str(b)],text=True);records[v]={};norm[v]={}
 for line in symbols.splitlines():
  if ('cast_numeric_arrays::<arrow_array::types::Int16Type, arrow_array::types::Int64Type>' in line or ('try_numeric_cast<arrow_array::types::Int16Type, arrow_array::types::Int64Type>' in line and 'try_unary::' in line)):
   addr,size,_,name=line.split(maxsplit=3);addr=int(addr,16);size=int(size,16);key='dispatch' if 'cast_numeric_arrays' in name else 'fallback'
   asm=subprocess.check_output(['objdump','-d','-C','--no-show-raw-insn',f'--start-address={addr}',f'--stop-address={addr+size}',str(b)],text=True)
   (q/f'final-{v}-{key}.asm').write_text(asm);norm[v][key]=normalize(asm,addr,size)
   records[v][key]={'address':hex(addr),'size_bytes':size,'instruction_count':len(norm[v][key].splitlines()),'normalized_sha256':hashlib.sha256(norm[v][key].encode()).hexdigest(),'datatype_drop_calls':sum('call' in s and 'drop_glue::<arrow_schema::datatype::DataType>' in s for s in asm.splitlines())}
assert norm['before']['fallback']==norm['after']['fallback']
# Check that the final Cargo dispatch has the same instruction shape as the diagnostic build.
asm=(q/'constant-types-dispatch.asm').read_text();m=re.search(r'\n([0-9a-f]+) <arrow_cast::cast::cast_numeric_arrays',asm);addr=int(m[1],16)
direct_size=json.loads((q/'diagnostic-assembly.json').read_text())['constant-types']['size_bytes']
assert norm['after']['dispatch']==normalize(asm,addr,direct_size)
assert records['after']['dispatch']['datatype_drop_calls']==0
