use arrow_array::{Array, Int16Array, cast::AsArray, types::Int64Type};
use arrow_buffer::NullBuffer;
use arrow_cast::{CastOptions, cast_with_options};
use arrow_schema::DataType;
use std::{hint::black_box, time::Instant};

fn main() {
    let args: Vec<_> = std::env::args().collect();
    let safe: bool = args[1].parse().unwrap();
    let null_mode = &args[2];
    let rows: usize = args[3].parse().unwrap();
    let casts = 8_388_608 / rows;
    let values: Vec<_> = (0..rows).map(|i| (i * 73) as i16).collect();
    let nulls = match null_mode.as_str() {
        "none" => None,
        "mixed" => Some(NullBuffer::from(
            (0..rows).map(|i| i % 5 != 0).collect::<Vec<_>>(),
        )),
        "near_half" => Some(NullBuffer::from(
            (0..rows)
                .map(|i| (i * 37) % rows >= rows * 49 / 100)
                .collect::<Vec<_>>(),
        )),
        "half" => Some(NullBuffer::from(
            (0..rows).map(|i| i % 2 == 0).collect::<Vec<_>>(),
        )),
        "majority" => Some(NullBuffer::from(
            (0..rows)
                .map(|i| (i * 37) % rows >= (rows * 51).div_ceil(100))
                .collect::<Vec<_>>(),
        )),
        "sparse" => Some(NullBuffer::from(
            (0..rows).map(|i| i % 100 == 0).collect::<Vec<_>>(),
        )),
        "all" => Some(NullBuffer::new_null(rows)),
        _ => panic!("unknown null mode"),
    };
    let input = Int16Array::new(values.into(), nulls);
    let options = CastOptions {
        safe,
        ..Default::default()
    };
    let cast = || {
        cast_with_options(
            black_box(&input),
            black_box(&DataType::Int64),
            black_box(&options),
        )
        .unwrap()
    };
    let output = cast();
    assert_eq!(output.data_type(), &DataType::Int64);
    for (value, expected) in output.as_primitive::<Int64Type>().iter().zip(input.iter()) {
        assert_eq!(value, expected.map(i64::from));
    }
    // Widening retains ordinary Arrow buffer ownership.
    let buffer = output.as_primitive::<Int64Type>().values().inner().clone();
    drop(output);
    assert!(buffer.into_mutable().is_ok());
    let mut samples = Vec::new();
    for round in 0..11 {
        let start = Instant::now();
        for _ in 0..casts {
            drop(black_box(cast()));
        }
        let ms = start.elapsed().as_secs_f64() * 1000.0;
        if round >= 2 {
            samples.push(ms);
        }
    }
    let null_count = input.null_count();
    println!(
        "{{\"safe\":{safe},\"null_mode\":\"{null_mode}\",\"rows_per_cast\":{rows},\"casts_per_sample\":{casts},\"null_count\":{null_count},\"samples_ms\":{samples:?}}}"
    );
}

